private String getFieldNameFromJsonPathPattern(String patter){
	String fieldName = null;
	if(!Validator.isBlank(patter)){
		int lastIndexOfOpenPattern = patter.lastIndexOf(ALPACA_FIELD_OPEN_PATTERN) + ALPACA_FIELD_OPEN_PATTERN.length();
		int lastIndexOfClosingPattern = patter.lastIndexOf(ALPACA_FIELD_CLOSING_PATTERN);
		fieldName = patter.substring(lastIndexOfOpenPattern, lastIndexOfClosingPattern);
	}
	return fieldName;
}

private List<String> filterPathByFieldList(List<String> paths, List<String> fieldList){
	List<String> retVal = null;
	if((paths != null && !paths.isEmpty()) && (fieldList != null && !fieldList.isEmpty())){
		retVal = paths.stream().filter(field -> {
			List<String> splittedPath = Arrays.asList(field.split(ALPACA_FIELD_CLOSING_PATTERN)).stream().map(splitted -> splitted.concat(ALPACA_FIELD_CLOSING_PATTERN)).collect(Collectors.toList());
			return splittedPath.containsAll(fieldList);
		}).collect(Collectors.toList());
	}

	return retVal;
}

private static List<String> removeFieldsFromPath(List<String> paths, List<String> fieldList){
	List<String> retVal = null;
	if((paths != null && !paths.isEmpty()) && (fieldList != null && !fieldList.isEmpty())){
		retVal = new ArrayList<>();
		for(String path : paths) {
			List<String> splittedPath = Arrays.asList(path.split(ALPACA_FIELD_CLOSING_PATTERN)).stream().map(splitted -> splitted.concat(ALPACA_FIELD_CLOSING_PATTERN)).collect(Collectors.toList());
			if(splittedPath.containsAll(fieldList)) {
				splittedPath.removeAll(fieldList);
				if(!splittedPath.isEmpty()) {
					retVal.add(splittedPath.get(0));
				}
			}
		}
	}

	return retVal;
}

